script:
(function () {
  'use strict';

  function $(id) { return document.getElementById(id); }

  var canvas = $('waveformCanvas');
  var canvasCtx = canvas.getContext('2d');
  var levelFill = $('levelFill');
  var levelPeak = $('levelPeak');
  var deviceSelect = $('deviceSelect');
  var btnStart = $('btnStartMic');
  var btnStop = $('btnStopMic');
  var diagnosticPanel = $('diagnosticPanel');
  var statPeakDb = $('statPeakDb');
  var statSampleRate = $('statSampleRate');
  var statClipping = $('statClipping');
  var statDeviceName = $('statDeviceName');
  var clipLog = $('clipLog');
  var optEcho = $('optEchoCancellation');
  var optNoise = $('optNoiseSuppression');
  var optAgc = $('optAutoGain');
  var infoSampleSize = $('infoSampleSize');
  var infoChannels = $('infoChannels');
  var infoEcho = $('infoEcho');
  var infoNoise = $('infoNoise');
  var infoAgc = $('infoAgc');
  var infoLatency = $('infoLatency');
  var btnQualityCheck = $('btnQualityCheck');
  var qualityProgress = $('qualityProgress');
  var qualityProgressFill = $('qualityProgressFill');
  var qualityPrompt = $('qualityPrompt');
  var qOut = {
    grade: $('qGrade'), clarity: $('qClarity'), headroom: $('qHeadroom'), peak: $('qPeak'),
    quiet: $('qQuiet'), clipping: $('qClipping'), volume: $('qVolume'), latency: $('qLatency'),
    maxFreq: $('qMaxFreq'), dynRange: $('qDynRange'), processing: $('qProcessing')
  };

  var MIN_DB = -60;

  var currentStream = null;
  var audioCtx = null;
  var analyser = null;
  var sourceNode = null;
  var rafId = null;
  var starting = false;
  var peakDb = MIN_DB;
  var peakHoldUntil = 0;
  var clipCount = 0;
  var clipCooldownUntil = 0;
  var sessionStartTime = 0;
  var currentInfo = null;
  var timeData = null;
  var floatData = null;
  var qualityTimer = null;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function show(el, on) { el.classList.toggle('u-hidden', !on); }

  function fmtDb(db) { return (db <= -120 || !isFinite(db)) ? '—' : db.toFixed(1) + ' dBFS'; }
  function onOff(v) { return v === true ? 'On' : v === false ? 'Off' : 'Not reported'; }
  function formatSeconds(s) {
    var m = Math.floor(s / 60), rem = Math.floor(s % 60);
    return m + ':' + (rem < 10 ? '0' : '') + rem;
  }

  function resizeCanvas() {
    var rect = canvas.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
  }

  function dbToPct(db) {
    // Map -60dB..0dB onto 0%..100% for the level meter / scale.
    var pct = ((db - MIN_DB) / -MIN_DB) * 100;
    return Math.max(0, Math.min(100, pct));
  }

  // Reads the analyser as Float32 where supported: 8-bit byte data bottoms
  // out around -42 dBFS, far too coarse for a quiet-gap / noise-floor reading.
  function readTimeDomain() {
    if (analyser.getFloatTimeDomainData) {
      analyser.getFloatTimeDomainData(floatData);
      return floatData;
    }
    analyser.getByteTimeDomainData(timeData);
    for (var i = 0; i < timeData.length; i++) floatData[i] = (timeData[i] - 128) / 128;
    return floatData;
  }

  function measureFrame() {
    var data = readTimeDomain();
    var sumSquares = 0, peakAbs = 0;
    for (var j = 0; j < data.length; j++) {
      var a = Math.abs(data[j]);
      if (a > peakAbs) peakAbs = a;
      sumSquares += data[j] * data[j];
    }
    var rms = Math.sqrt(sumSquares / data.length);
    return {
      data: data,
      rmsDb: rms > 0 ? 20 * Math.log10(rms) : -120,
      peakDb: peakAbs > 0 ? 20 * Math.log10(peakAbs) : -120,
      saturated: peakAbs >= 0.99
    };
  }

  function drawWave(data) {
    var w = canvas.width, h = canvas.height;
    canvasCtx.lineWidth = Math.max(1, w / 400);
    canvasCtx.strokeStyle = '#7c5cff';
    canvasCtx.beginPath();
    var slice = w / data.length;
    for (var i = 0; i < data.length; i++) {
      var y = (1 - data[i]) * h / 2;
      if (i === 0) canvasCtx.moveTo(0, y); else canvasCtx.lineTo(i * slice, y);
    }
    canvasCtx.stroke();
  }

  function drawFrame() {
    rafId = requestAnimationFrame(drawFrame);
    if (!analyser) return;

    var f = measureFrame();
    canvasCtx.clearRect(0, 0, canvas.width, canvas.height);
    drawWave(f.data);

    var db = Math.max(MIN_DB, f.rmsDb);
    levelFill.style.width = dbToPct(db) + '%';

    // Hold the peak for ~1.2s so brief transients (claps, plosives) stay
    // visible instead of flickering past at 60fps, then let it decay back
    // down rather than staying stuck forever after a single loud moment.
    var now = performance.now();
    var framePeak = Math.max(MIN_DB, f.peakDb);
    if (framePeak > peakDb) {
      peakDb = framePeak;
      peakHoldUntil = now + 1200;
    } else if (now > peakHoldUntil) {
      peakDb = Math.max(framePeak, peakDb - 0.6, MIN_DB);
    }
    levelPeak.style.left = dbToPct(peakDb) + '%';
    statPeakDb.textContent = Math.round(peakDb) + ' dB';

    // A 1.5s cooldown between logged events turns one sustained loud
    // moment into a single row instead of dozens at 60fps.
    if (f.saturated && now > clipCooldownUntil) {
      clipCooldownUntil = now + 1500;
      clipCount++;
      statClipping.textContent = String(clipCount);
      var elapsedS = Math.round((now - sessionStartTime) / 1000);
      var row = document.createElement('div');
      row.className = 'info-row';
      row.innerHTML = '<span class="info-label">' + formatSeconds(elapsedS) + ' into session</span><span class="info-value">Input clipped</span>';
      clipLog.appendChild(row);
      show(clipLog, true);
      // Cap the visible log at the 5 most recent events so it can't grow
      // unbounded over a long session.
      var rows = clipLog.querySelectorAll('.info-row');
      if (rows.length > 5) rows[0].remove();
    }
  }

  function cancelQualityCheck() {
    if (qualityTimer) { clearInterval(qualityTimer); qualityTimer = null; }
    qualityProgress.hidden = true;
    btnQualityCheck.textContent = 'Run 8-Second Quality Check';
  }

  // Same overall shape as every camera tool's stopStream() elsewhere on
  // this site (see webcam-test-online / this project's CLAUDE.md) — audio
  // teardown additionally closes the AudioContext, which a camera-only
  // tool never needs to do.
  function stopStream() {
    cancelQualityCheck();
    if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    if (audioCtx) {
      audioCtx.close().catch(function () {});
      audioCtx = null;
    }
    analyser = null;
    sourceNode = null;
    levelFill.style.width = '0%';
    levelPeak.style.left = '0%';
    canvasCtx.clearRect(0, 0, canvas.width, canvas.height);
    btnStop.disabled = true;
    btnQualityCheck.disabled = true;
    statPeakDb.textContent = '—';
    statSampleRate.textContent = '—';
    statClipping.textContent = '0';
    statDeviceName.textContent = '—';
    [infoSampleSize, infoChannels, infoEcho, infoNoise, infoAgc, infoLatency].forEach(function (el) { el.textContent = '—'; });
    clipLog.innerHTML = '<div class="info-section-label">Recent Clipping (input too loud)</div>';
    show(clipLog, false);
    peakDb = MIN_DB;
    peakHoldUntil = 0;
    clipCount = 0;
    clipCooldownUntil = 0;
    currentInfo = null;
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Microphone access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No microphone was detected.</strong> Connect a microphone and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your microphone is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This microphone doesn’t support the requested settings.</strong> Try another microphone from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Microphone access requires HTTPS.</strong>' };
      case 'AbortError':
        return { sev: 'warn', html: 'The microphone request was interrupted. Click <strong>Start Microphone</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the microphone.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var mics = devices.filter(function (d) { return d.kind === 'audioinput'; });
    deviceSelect.innerHTML = '';
    mics.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Microphone ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = mics.length === 0;
  }

  function latencyMs(settings) {
    if (typeof settings.latency === 'number' && settings.latency > 0) return settings.latency * 1000;
    if (audioCtx && typeof audioCtx.baseLatency === 'number' && audioCtx.baseLatency > 0) return audioCtx.baseLatency * 1000;
    return null;
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting microphone access…' }]);
    btnStart.disabled = true;

    var audioConstraint = {
      echoCancellation: optEcho.checked,
      noiseSuppression: optNoise.checked,
      autoGainControl: optAgc.checked
    };
    if (deviceId) audioConstraint.deviceId = { exact: deviceId };
    navigator.mediaDevices.getUserMedia({ audio: audioConstraint, video: false })
      .then(function (stream) {
        currentStream = stream;
        audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        // AudioContext starts suspended under autoplay policy in some
        // browsers -- resume() here runs inside the click handler chain
        // (a real user gesture), which is what makes resume() reliable.
        return audioCtx.resume().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        sourceNode = audioCtx.createMediaStreamSource(stream);
        analyser = audioCtx.createAnalyser();
        analyser.fftSize = 2048;
        analyser.smoothingTimeConstant = 0.4;
        timeData = new Uint8Array(analyser.fftSize);
        floatData = new Float32Array(analyser.fftSize);
        sourceNode.connect(analyser);
        // Deliberately NOT connected to audioCtx.destination -- this is a
        // level meter, not a monitor. Routing a live mic to speakers
        // without an explicit opt-in creates a feedback loop; the
        // dedicated echo-test tool handles that case with its own
        // explicit safety gating.

        var track = stream.getAudioTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        var lat = latencyMs(settings);
        currentInfo = {
          device: track.label || 'Microphone',
          sampleRate: settings.sampleRate || audioCtx.sampleRate,
          sampleSize: settings.sampleSize || null,
          channels: settings.channelCount || null,
          echo: settings.echoCancellation,
          noise: settings.noiseSuppression,
          agc: settings.autoGainControl,
          latency: lat
        };
        statSampleRate.textContent = currentInfo.sampleRate ? (currentInfo.sampleRate + ' Hz') : 'Not reported';
        statDeviceName.textContent = currentInfo.device;
        infoSampleSize.textContent = currentInfo.sampleSize ? currentInfo.sampleSize + ' bits' : 'Not reported';
        infoChannels.textContent = currentInfo.channels ? (currentInfo.channels + (currentInfo.channels === 1 ? ' (mono)' : ' (stereo)')) : 'Not reported';
        infoEcho.textContent = onOff(currentInfo.echo);
        infoNoise.textContent = onOff(currentInfo.noise);
        infoAgc.textContent = onOff(currentInfo.agc);
        infoLatency.textContent = lat ? lat.toFixed(1) + ' ms' : 'Not reported';

        resizeCanvas();
        sessionStartTime = performance.now();
        drawFrame();

        btnStop.disabled = false;
        btnQualityCheck.disabled = false;
        qualityPrompt.textContent = 'Ready. Click Run 8-Second Quality Check, stay quiet for 3 seconds, then read a sentence at your normal level.';
        setDiagnostic([{ sev: 'ok', html: '<strong>Microphone is live.</strong> Speak or make noise to see the meter respond. Nothing is recorded or uploaded.' }]);

        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  // ---- Quality check: quiet gap, then speech --------------------------------
  function percentile(arr, p) {
    if (!arr.length) return -120;
    var s = arr.slice().sort(function (a, b) { return a - b; });
    return s[Math.min(s.length - 1, Math.max(0, Math.round((s.length - 1) * p)))];
  }

  function gradeFor(r) {
    if (r.clipped) return 'Poor — clipping';
    if (r.peak < -40) return 'Poor — too quiet';
    var g;
    if (r.clarity >= 45) g = 'Excellent';
    else if (r.clarity >= 35) g = 'Good';
    else if (r.clarity >= 20) g = 'Fair';
    else g = 'Poor';
    if ((r.peak < -24 || r.peak > -3) && (g === 'Excellent' || g === 'Good')) g = 'Good — adjust level';
    return g;
  }

  function runQualityCheck() {
    if (!analyser) return;
    if (qualityTimer) { cancelQualityCheck(); qualityPrompt.textContent = 'Quality check cancelled.'; return; }
    var QUIET_MS = 3000, SPEECH_MS = 5000, STEP = 50;
    var quietLevels = [], speechPeak = -120, speechLevels = [], clipped = false;
    var t0 = performance.now();
    qualityProgress.hidden = false;
    qualityProgressFill.style.width = '0%';
    btnQualityCheck.textContent = 'Cancel Quality Check';
    qualityPrompt.textContent = 'Stay quiet… measuring the quiet gap (room and mic noise).';
    // Timer-driven rather than requestAnimationFrame, so it keeps sampling
    // even if the drawing loop is throttled.
    qualityTimer = setInterval(function () {
      if (!analyser) { cancelQualityCheck(); return; }
      var el = performance.now() - t0;
      var f = measureFrame();
      if (el < QUIET_MS) {
        if (el > 400) quietLevels.push(f.rmsDb);
      } else {
        if (quietLevels.length && speechLevels.length === 0 && speechPeak === -120) {
          qualityPrompt.textContent = 'Now speak: read a sentence at your normal level and distance.';
        }
        speechLevels.push(f.rmsDb);
        if (f.peakDb > speechPeak) speechPeak = f.peakDb;
        if (f.saturated) clipped = true;
      }
      qualityProgressFill.style.width = Math.min(100, el / (QUIET_MS + SPEECH_MS) * 100) + '%';
      if (el >= QUIET_MS + SPEECH_MS) {
        clearInterval(qualityTimer);
        qualityTimer = null;
        finishQuality(percentile(quietLevels, 0.5), speechPeak, percentile(speechLevels, 0.9), clipped);
      }
    }, STEP);
  }

  function finishQuality(quiet, peak, speech, clipped) {
    qualityProgress.hidden = true;
    btnQualityCheck.textContent = 'Run Quality Check Again';
    var r = { quiet: quiet, peak: peak, speech: speech, clipped: clipped };
    r.clarity = peak - quiet;
    r.headroom = -peak;
    r.grade = gradeFor(r);
    var info = currentInfo || {};
    var bits = info.sampleSize || 16;
    r.dynRange = Math.round(6.02 * bits + 1.76);
    r.maxFreq = info.sampleRate ? info.sampleRate / 2000 : null;
    r.volume = peak < -24 ? 'Too quiet — raise input gain or move closer' : peak > -3 ? 'Too loud — lower input gain' : peak > -6 ? 'Loud — little headroom' : 'Good (peaks between −24 and −6 dBFS)';
    r.latency = info.latency == null ? 'Not reported' : info.latency < 30 ? 'Good (' + info.latency.toFixed(1) + ' ms)' : info.latency < 60 ? 'Noticeable (' + info.latency.toFixed(1) + ' ms)' : 'High (' + info.latency.toFixed(1) + ' ms)';
    var on = [];
    if (info.echo) on.push('echo cancellation');
    if (info.noise) on.push('noise suppression');
    if (info.agc) on.push('auto gain');
    r.processing = on.length ? 'On: ' + on.join(', ') + ' — readings describe the processed stream' : 'All browser processing off — raw microphone';

    qOut.grade.textContent = r.grade;
    qOut.clarity.textContent = r.clarity.toFixed(1) + ' dB';
    qOut.headroom.textContent = r.headroom.toFixed(1) + ' dB';
    qOut.peak.textContent = fmtDb(peak);
    qOut.quiet.textContent = fmtDb(quiet);
    qOut.clipping.textContent = clipped ? 'Yes — input hit full scale' : 'None';
    qOut.volume.textContent = r.volume;
    qOut.latency.textContent = r.latency;
    qOut.maxFreq.textContent = r.maxFreq ? r.maxFreq.toFixed(2) + ' kHz' : '—';
    qOut.dynRange.textContent = r.dynRange + ' dB (' + bits + '-bit)';
    qOut.processing.textContent = r.processing;
    qualityPrompt.textContent = 'Done: ' + r.grade + '. Signal clarity is the gap between your speech peak and the quiet gap.';
  }

  // ---- Events ---------------------------------------------------------------
  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Microphone stopped. Click <strong>Start Microphone</strong> to test again.' }]);
  });
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });
  [optEcho, optNoise, optAgc].forEach(function (el) {
    el.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });
  });
  btnQualityCheck.addEventListener('click', runQualityCheck);
  window.addEventListener('resize', resizeCanvas);

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  resizeCanvas();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support microphone access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
